36 | /**
37 |  * This provides a master servlet for dealing with short urls.  It mostly does
38 |  * redirects to the proper JSP pages. It also intercepts the servlet
39 |  * shutdown events and uses it to signal wiki shutdown.
40 |  *
41 |  * @since 2.2
42 |  */
43 | public class WikiServlet extends HttpServlet {
44 | 
45 |     private static final long serialVersionUID = 3258410651167633973L;
46 |     private WikiEngine m_engine;
47 |     static final Logger log = Logger.getLogger( WikiServlet.class.getName() );
48 | 
49 |     /**
50 |      * {@inheritDoc}
51 |      */
52 |     @Override
53 |     public void init( ServletConfig config ) throws ServletException {
54 |         super.init( config );
55 |         m_engine = WikiEngine.getInstance( config );
56 |         log.info( "WikiServlet initialized." );
57 |     }
58 | 
59 |     /**
60 |      * Destroys the WikiServlet; called by the servlet container
61 |      * when shutting down the webapp. This method calls the
62 |      * protected method {@link WikiEngine#shutdown()}, which
63 |      * sends {@link org.apache.wiki.event.WikiEngineEvent#SHUTDOWN}
64 |      * events to registered listeners.
65 |      *
66 |      * @see javax.servlet.GenericServlet#destroy()
67 |      */
68 |     @Override
69 |     public void destroy() {
70 |         log.info( "WikiServlet shutdown." );
71 |         CacheManager.getInstance().shutdown();
72 |         m_engine.shutdown();
73 |         super.destroy();
74 |     }
75 | 
76 |     /**
77 |      * {@inheritDoc}
78 |      */
79 |     @Override
80 |     public void doPost( HttpServletRequest req, HttpServletResponse res ) throws IOException, ServletException {
81 |         doGet( req, res );
82 |     }
83 | 
84 |     /**
85 |      * {@inheritDoc}
86 |      */
87 |     @Override
88 |     public void doGet( HttpServletRequest req, HttpServletResponse res ) throws IOException, ServletException {
89 |         String pageName = DefaultURLConstructor.parsePageFromURL( req, m_engine.getContentEncoding() );
90 | 
91 |         log.info( "Request for page: " + pageName );
92 |         if( pageName == null ) {
93 |             pageName = m_engine.getFrontPage(); // FIXME: Add special pages as well
94 |         }
95 | 
96 |         String jspPage = m_engine.getURLConstructor().getForwardPage( req );
97 |         RequestDispatcher dispatcher = req.getRequestDispatcher( "/" + jspPage + "?page=" +
98 |                                                                  m_engine.encodeName( pageName ) + "&" + req.getQueryString() );
99 | 
100 |         dispatcher.forward( req, res );
101 |     }
102 | 
103 | }

