19 | package org.apache.wiki.url;
20 | 
21 | import java.util.Properties;
22 | import java.io.IOException;
23 | import javax.servlet.http.HttpServletRequest;
24 | 
25 | import org.apache.wiki.WikiEngine;
26 | 
27 | 
28 | /**
29 |  *  Provides an interface through which JSPWiki constructs URLs.
30 |  *  JSPWiki calls the methods of this interface whenever an URL
31 |  *  that points to any JSPWiki internals is required.  For example,
32 |  *  if you need to find an URL to the editor page for page "TextFormattingRules",
33 |  *  you would call makeURL( WikiContext.EDIT, "TextFormattingRules", false, null );
34 |  *
35 |  *  @since 2.2
36 |  */
37 | public interface URLConstructor {
38 |     /**
39 |      *  Initializes.  Note that the engine is not fully initialized at this
40 |      *  point, so don't do anything fancy here - use lazy init, if you have to.
41 |      *
42 |      *  @param  engine The WikiEngine that this URLConstructor belongs to
43 |      *  @param properties Properties used to initialize
44 |      */
45 |     void initialize( WikiEngine engine, Properties properties );
46 | 
47 |     /**
48 |      *  Constructs the URL with a bunch of parameters.
49 |      *
50 |      *  @param context The request context (@see WikiContext) that you want the URL for
51 |      *  @param name The page name (or in case of WikiContext.NONE, the auxiliary JSP page
52 |      *              or resource you want to point at).  This must be URL encoded.  Null is NOT safe.
53 |      *  @param absolute True, if you need an absolute URL.  False, if both relative and absolute URLs are fine.
54 |      *  @param parameters An URL parameter string (these must be URL-encoded, and separated with &amp;amp;)
55 |      *  @return An URL pointing to the resource.  Must never return null - throw an InternalWikiException  if something goes wrong.
56 |      */
57 |     String makeURL( String context, String name, boolean absolute, String parameters );
58 | 
59 |     /**
60 |      *  Should parse the "page" parameter from the actual request. This is essentially the reverse of makeURL() - whenever
61 |      *  a request constructed by calls to makeURL() is passed to this routine, it MUST be able to parse the resource name
62 |      *  (WikiPage, Attachment, other resource) from the request.
63 |      *
64 |      *  @param context In which request context the request was made (this should help in parsing)
65 |      *  @param request The HTTP request that was used when coming here
66 |      *  @param encoding The encoding with which the request was made (UTF-8 or ISO-8859-1).
67 |      *  @return This method must return the name of the resource.
68 |      *  @throws IOException If parsing failes
69 |      */
70 |     String parsePage( String context, HttpServletRequest request, String encoding ) throws IOException;
71 | 
72 |     /**
73 |      *  Returns information which JSP page should continue handling this type of request.
74 |      *
75 |      * @param request The HTTP Request that was used to end up in this page.
76 |      * @return "Wiki.jsp", "PageInfo.jsp", etc.  Just return the name, JSPWiki will figure out the page.
77 |      */
78 |     String getForwardPage( HttpServletRequest request );
79 | 
80 | }

