18 | ###########################################################################
19 | #
20 | #  This is the JSPWiki configuration file.  You'll need to edit this
21 | #  a bit.  The first few lines are the most important ones.
22 | #
23 | #  If you don't want to edit this file, you can override each individual
24 | #  property by specifying the property name as a standard
25 | #  Java System Property.
26 | #
27 | #  Wherever it is said that an option can be "true" or "false", you can
28 | #  also use "yes"/"no", or "on/off".  Just for some convenience.
29 | #
30 | #
31 | #  You can use this to override the default application name.  It affects
32 | #  the HTML titles and logging, for example.  It can be different from
33 | #  the actual web name (http://my.com/mywiki) of the application, but usually
34 | #  it is the same.
35 | #
36 | jspwiki.applicationName = JSPWiki
37 | 
38 | #
39 | #  Which page provider class to use.  Possibilities are:
40 | #
41 | #    FileSystemProvider     - for simple pure file storage with no version information
42 | #    VersioningFileProvider - for simple pure file storage with    version information
43 | #
44 | jspwiki.pageProvider = FileSystemProvider
45 | 
46 | #
47 | # How to order pages in various lists and plugins.  By default, they are
48 | # ordered using Java's "natural" String order (purely character by character
49 | # comparison). This means that the pages named "Page1", "Page2" and "Page10"
50 | # appear in the order "Page1", "Page10", "Page2".
51 | #
52 | # To specify a different ordering, give the fully qualified name of a String
53 | # Comparator. If the class can't be found, an error will be logged and page
54 | # sorting will fall back to the default "natural" ordering. You can specify
55 | # any String Comparator class here BUT be careful of using case insensitive
56 | # comparators as JSPWiki page names may be case sensitive.
57 | # Example: jspwiki.pageNameComparator.class = my.fully.qualified.comparator
58 | #
59 | # For convenience, we have provided a few possibly useful comparators:
60 | #
61 | # HumanComparator understands numbers and sorts in a more human friendly
62 | # order (English only).  Using HumanComparator, the pages "Page1", "Page2",
63 | # "Page10" will sort in that order.
64 | # Example: jspwiki.pageNameComparator.class = HumanComparator
65 | #
66 | # LocaleComparator uses the server's Locale for ordering.  Useful if your
67 | # content is always in a language other than English.  Does not do human
68 | # friendly numeric ordering.
69 | # Example: jspwiki.pageNameComparator.class = LocaleComparator
70 | #
71 | #jspwiki.pageNameComparator.class =
72 | 
73 | #
74 | #  Set to true, if you want to cache page data into memory.  This is
75 | #  in general a good idea.
76 | #
77 | #  Default is false (no cache).
78 | #
79 | #  NB: This replaces the JSPWiki 1.x "CachingProvider" setting, since it
80 | #      probably was too confusing.
81 | #
82 | jspwiki.usePageCache = true
83 | 
84 | #
85 | #  Determines where wiki files are kept for FileSystemProvider i.e.:
86 | #
87 | #  jspwiki.fileSystemProvider.pageDir = /p/web/www-data/jspwiki/
88 | #
89 | #  If you're using Windows, then you must duplicate the backslashes.
90 | #  For example, use:
91 | #
92 | #  jspwiki.fileSystemProvider.pageDir = C:\\Data\\jspwiki
93 | #
94 | #  If not provided, will default to a "jspwiki-files" directory
95 | #  in the user's home folder.
96 | #
97 | 
98 | 
99 | #
100 | #  The JSPWiki working directory.  If not set, a temporary path will
101 | #  be used.  You can see the location of the workdir in the logs.
102 | #  It is HIGHLY recommended that you set this.
103 | #
104 | #  The working directory is used to cache things like Lucene search
105 | #  results.
106 | #
107 | #jspwiki.workDir =
108 | 
109 | #
110 | #  ATTACHMENTS:
111 | #
112 | #  Use the following property to define which attachment provider
113 | #  you want to use.  You have basically two choices:
114 | #    * Set the value to BasicAttachmentProvider
115 | #      a simple, flat file versioning provider
116 | #    * Leave the value empty (or just comment the line out)
117 | #      the attachment functionality is disabled
118 | #
119 | jspwiki.attachmentProvider = BasicAttachmentProvider
120 | 
121 | #
122 | #  The BasicAttachmentProvider needs to know where to store the files
123 | #  the user has uploaded.  It's okay to put these in the same directory
124 | #  as you put your text files (i.e. the pageDir setting above).
125 | #
126 | #  If you're using Windows, then you must duplicate the backslashes.
127 | #  For example, use:
128 | #
129 | #  jspwiki.basicAttachmentProvider.storageDir = C:\\Data\\jspwiki
130 | #
131 | #  If not provided, will default to a "jspwiki-files" directory
132 | #  in the user's home folder.
133 | #
134 | 
135 | #
136 | #  You can tell the BasicAttachmentProvider to add a flag
137 | #  so that browsers do not cache certain (or all) attachment
138 | #  types. This is useful in intranet environments. You should activate
139 | #  this if your users complain that their excel files are not uploaded
140 | #  correctly and they still do have an old version: Usually the
141 | #  file was uploaded correctly, but they get the locally cached version
142 | #
143 | #  You can use regular expressions to disable the cache, e.g the
144 | #  following example will disable browser cache for all excel and word files
145 | #
146 | #  If you don't define this property, cache is enabled by default for
147 | #  all attachments
148 | #
149 | #  jspwiki.basicAttachmentProvider.disableCache = .*\.xls|.*\.doc
150 | 
151 | #
152 | #  You can limit the maximum size of an attachment by setting this
153 | #  value.  The value is in bytes, and by default all attachments
154 | #  are accepted.
155 | # This limit is not enforced for users with AdminPermissions.
156 | #
157 | #  The following line would limit the attachment size to 100,000 bytes
158 | #jspwiki.attachment.maxsize=100000
159 | 
160 | #
161 | #  By default JSPWiki accepts all types of attachments.  However, you
162 | #  can allow some types only, or forbid some other types.  By default,
163 | #  all file types are allowed (if you do not specify the "allow" list
164 | #  at all or it is empty).
165 | # These allow/forbid statements are not enforced for users with AdminPermissions.
166 | #
167 | #  These both are space-separated lists of file suffixes
168 | #
169 | #  Example: Allow only PNG, JPG, ZIP and JAR file attachments
170 | #jspwiki.attachment.allowed=.png .jpg .zip .jar
171 | 
172 | #  Example: Forbid HTML, PHP, ASP and EXE
173 | #jspwiki.attachment.forbidden=.html .htm .php .asp .exe
174 | 
175 | #
176 | #  page Diff Representation
177 | #
178 | #  To show differences between page versions, you can define a
179 | # difference provider.
180 | #  The following choices are available:
181 | #    * TraditionalDiffProvider - Uses internal (java) diff
182 | #        to create a list of changes and shows it line by
183 | #        line colored. This is the default
