407 | #############################################################################
408 | #
409 | #  URL Constructor
410 | #
411 | #  JSPWiki by default generates page and attachment links that use JSP
412 | #  pages and request parameters. It can also use alternative URL
413 | #  constructors so that URL pages resemble traditional website paths, too.
414 | #  You have three choices for generating URLs:
415 | #
416 | #     DefaultURLConstructor - uses JSPs for all references:
417 | #         http://mywiki.com/jspwiki/Wiki.jsp?page=Main
418 | #         http://mywiki.com/jspwiki/Edit.jsp?page=Main
419 | #
420 | #     ShortURLConstructor - uses path-like reference style:
421 | #         http://mywiki.com/jspwiki/wiki/Main
422 | #         http://mywiki.com/jspwiki/wiki/Main?do=Edit
423 | #
424 | #     ShortViewURLConstructor - uses path-like references for views; JSPs for everything else:
425 | #         http://mywiki.com/jspwiki/wiki/Main
426 | #         http://mywiki.com/jspwiki/Edit.jsp?page=Main
427 | #
428 | #  Of course, you can also write your own implementation if you wish.
429 | #
430 | #  For either of the ShortURL constructors, you can also specify a
431 | #  prefix path to go in front of page names. By default, the
432 | #  prefix is 'wiki/'.
433 | #
434 | #  Be warned that the ShortURLConstructor does not work well with any other editor
435 | #  except the built-in plaintext one.  Use ShortViewURLConstructor if you plan
436 | #  to enable any other ones.
437 | #
438 | #jspwiki.urlConstructor = DefaultURLConstructor
439 | #jspwiki.urlConstructor = ShortViewURLConstructor
440 | #jspwiki.shortURLConstructor.prefix = wiki/
441 | #  This prefix must be in some elements of web.xml, too: in
442 | #  servlet-mapping of WikiServlet, in filter-mapping of WikiJSPFilter
