707 | ###########################################################################
708 | #
709 | #  Determine how the RSS (Rich Site Summary) file generation should work.
710 | #  RSS is a standard pioneered by Netscape, which allows you to join your
711 | #  Wiki with a huge number of different news services around the world.
712 | #  Try a Google search on RSS and see what you can do with it.
713 | #
714 | #  All of these settings were added in JSPWiki 1.7.6.
715 | #
716 | #  Determine if the RSS file should be generated at all.  Allowed values
717 | #  are "true" and "false".  Default is "false".
718 | #
719 | jspwiki.rss.generate = false
720 | 
721 | #
722 | #  Determine the name of the RSS file. This path is relative to your
723 | #  Wiki root.  Default is "rss.rdf"
724 | #
725 | jspwiki.rss.fileName = rss.rdf
726 | 
727 | #
728 | #  Determine the refresh interval (ie. how often the RSS file is regenerated.
729 | #  It is not recommended to make this too often, or you'll choke your server.
730 | #  Anything above five minutes is probably okay.  The default value is one hour.
731 | #  The value should be in seconds.
732 | #
733 | jspwiki.rss.interval = 3600
734 | 
735 | #
736 | #  The text you want to be shown as your "channel description" when someone
